#!/usr/bin/env python3
"""news-image-20261120 entry: writes the pre-rendered front-page PNG.

Standard library only, no network, deterministic: the embedded PNG bytes
are written verbatim to $MAKEFUN_OUTPUT_DIR/entry.png (or /output).
The image itself is a newspaper front page for Friday 20 November 2026:
Cyclone Akvan landfall in Odisha as the hero story, plus the ICJ Myanmar
genocide verdict, embassies hit in Kyiv, and Huang's fall.
"""
import base64
import hashlib
import os
import struct

EXPECTED_SHA256 = "0a2a154fd7db271d1b312baf7bb382deda9f897548b16f7280be8016fe3dd3d2"
DATA_B64 = (
    ""
)


def main():
    raw = base64.b64decode(DATA_B64, validate=True)
    if raw[:8] != b"\x89PNG\r\n\x1a\n":
        raise SystemExit("not a PNG")
    if len(raw) > 1048576:
        raise SystemExit("PNG over 1 MiB")
    if hashlib.sha256(raw).hexdigest() != EXPECTED_SHA256:
        raise SystemExit("sha256 mismatch")
    # IHDR: bytes 16-24 hold width and height (big-endian uint32).
    if raw[12:16] != b"IHDR":
        raise SystemExit("PNG has no IHDR first")
    width, height = struct.unpack(">II", raw[16:24])
    if width > 1024 or height > 1024:
        raise SystemExit(f"PNG too large: {width}x{height}")
    print("PNG OK:", width, "x", height)
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(outdir, exist_ok=True)
    path = os.path.join(outdir, "entry.png")
    with open(path, "wb") as f:
        f.write(raw)
    print("wrote", path, len(raw), "bytes")


if __name__ == "__main__":
    main()
